import java.util.Scanner;

public class MultiCatch {
    public static void main(String[] args) {
        int[] values = {10, 20, 30};
        Scanner input = new Scanner(System.in);

        try {
            System.out.print("Enter an index (0-2): ");
            int index = input.nextInt();

            System.out.print("Enter a divisor: ");
            int divisor = input.nextInt();

            System.out.println("Result: " + (values[index] / divisor));

        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println("That index is outside the array.");
        } catch (ArithmeticException e) {
            System.out.println("You cannot divide by zero.");
        } catch (Exception e) {
            System.out.println("Something else went wrong: " + e.getMessage());
        }
    }
}

catch (ArrayIndexOutOfBoundsException | ArithmeticException e) {
    System.out.println("Bad input: " + e.getMessage());
}

static void level3() {
    System.out.println("level3 start");
    int x = 10 / 0;                 // throws here
    System.out.println("level3 end");   // never runs
}

static void level2() {
    System.out.println("level2 start");
    level3();
    System.out.println("level2 end");   // never runs
}

